import bruzem

def _detect_window_convention():
    """Detect how bruzem.window interprets its indices."""
    test_seq = list(range(6))          # [0, 1, 2, 3, 4, 5]
    # Call with the same arguments we intend to use later
    observed = bruzem.window(test_seq, 2, 5)

    # Expected outcomes for the four plausible conventions
    if observed == [2, 3, 4, 5]:
        # 0‑based, inclusive end
        return lambda seq, a, b: bruzem.window(seq, a, b)
    if observed == [2, 3, 4]:
        # 0‑based, exclusive end (like slice)
        return lambda seq, a, b: bruzem.window(seq, a, b + 1)
    if observed == [1, 2, 3, 4]:
        # 1‑based, inclusive end
        return lambda seq, a, b: bruzem.window(seq, a + 1, b + 1)
    if observed == [1, 2, 3]:
        # 1‑based, exclusive end
        return lambda seq, a, b: bruzem.window(seq, a + 1, b + 2)

    raise RuntimeError("Unable to determine bruzem.window indexing convention")

